-- ScholarshipHive Processing Portal — UPGRADE a live portal (keeps everything already typed into the portal)
-- Run ONCE in phpMyAdmin > Import, on the existing database. Take a backup first (cPanel > Backup).
-- If you run it a second time it stops at the first line with "Duplicate column" and changes nothing.
SET NAMES utf8mb4;

ALTER TABLE students
  ADD COLUMN import_key VARCHAR(60) NULL AFTER id,
  ADD COLUMN country VARCHAR(20) NOT NULL DEFAULT 'italy' AFTER import_key,
  ADD COLUMN sr_no INT NULL AFTER country,
  ADD COLUMN process_status VARCHAR(20) NULL AFTER sr_no,
  ADD COLUMN refund_reason VARCHAR(255) NULL AFTER refund,
  ADD COLUMN dues VARCHAR(40) NULL AFTER refund_reason,
  ADD COLUMN study_level VARCHAR(30) NULL AFTER received_date,
  ADD COLUMN applied_for VARCHAR(255) NULL AFTER study_level,
  ADD COLUMN last_degree VARCHAR(255) NULL AFTER applied_for,
  ADD COLUMN gpa VARCHAR(100) NULL AFTER last_degree,
  ADD COLUMN ielts VARCHAR(40) NULL AFTER gpa,
  ADD COLUMN contact_no VARCHAR(40) NULL AFTER ielts,
  ADD COLUMN client_type VARCHAR(30) NULL AFTER contact_no,
  ADD COLUMN recording_note VARCHAR(255) NULL AFTER drive_link,
  ADD COLUMN remarks_date DATE NULL AFTER remarks,
  ADD COLUMN meeting_date DATE NULL AFTER meeting_priority,
  ADD COLUMN tax_remarks TEXT NULL AFTER follow_up_3,
  ADD COLUMN recovery_email VARCHAR(150) NULL AFTER student_email,
  ADD COLUMN cv_status VARCHAR(20) NULL AFTER portal_password_enc,
  ADD COLUMN sop_status VARCHAR(20) NULL AFTER cv_status,
  ADD COLUMN campus_france VARCHAR(255) NULL AFTER sop_status,
  ADD COLUMN mock_interview VARCHAR(20) NULL AFTER campus_france,
  ADD COLUMN shortlisted_course VARCHAR(255) NULL AFTER shortlisting,
  ADD COLUMN admission_university VARCHAR(255) NULL AFTER shortlisted_course,
  ADD COLUMN application_fees VARCHAR(100) NULL AFTER admission_university,
  ADD COLUMN admission_letters VARCHAR(100) NULL AFTER application_status,
  ADD COLUMN embassy_status VARCHAR(100) NULL AFTER admission_letters,
  ADD COLUMN legalization_status VARCHAR(60) NULL AFTER embassy_status,
  ADD COLUMN second_consultancy VARCHAR(100) NULL AFTER legalization_status,
  ADD COLUMN application_notes TEXT NULL AFTER second_consultancy,
  ADD COLUMN record_remarks TEXT NULL AFTER application_notes,
  ADD COLUMN record_remarks_date DATE NULL AFTER record_remarks,
  MODIFY consult1 VARCHAR(20) NULL,
  MODIFY consent VARCHAR(20) NULL,
  MODIFY docs_checklist VARCHAR(20) NULL,
  MODIFY initial_meeting VARCHAR(30) NULL,
  MODIFY recorded_uploaded VARCHAR(30) NULL,
  MODIFY drive_link TEXT NULL,
  MODIFY meeting_priority VARCHAR(20) NULL,
  MODIFY second_meeting VARCHAR(20) NULL,
  MODIFY tax_meeting VARCHAR(20) NULL,
  MODIFY offer VARCHAR(20) NULL,
  MODIFY consult2 VARCHAR(20) NULL,
  MODIFY disc2 TEXT NULL,
  MODIFY enrollment VARCHAR(20) NULL,
  MODIFY consult3 VARCHAR(20) NULL,
  MODIFY disc3 TEXT NULL,
  MODIFY visa VARCHAR(20) NULL,
  MODIFY last_installment VARCHAR(60) NULL,
  MODIFY refund VARCHAR(40) NULL,
  MODIFY intake VARCHAR(40) NULL,
  MODIFY documents_status VARCHAR(255) NULL,
  MODIFY pending_documents TEXT NULL,
  MODIFY documents_link TEXT NULL,
  MODIFY shortlisting VARCHAR(30) NULL,
  MODIFY application_status VARCHAR(255) NULL,
  MODIFY refund_threat TEXT NULL,
  MODIFY financial_missing TEXT NULL,
  ADD UNIQUE KEY uq_import (import_key),
  ADD KEY idx_country (country);
ALTER TABLE users
  MODIFY role ENUM('admin','officer','tax','student') NOT NULL,
  ADD COLUMN countries VARCHAR(100) NULL AFTER team;
CREATE TABLE applications (
  id           INT UNSIGNED NOT NULL AUTO_INCREMENT,
  import_key   VARCHAR(80)  NULL,
  student_id   INT UNSIGNED NOT NULL,
  list_name    VARCHAR(60)  NULL,
  sort_no      VARCHAR(10)  NULL,
  university   VARCHAR(255) NULL,
  program      TEXT NULL,
  app_type     VARCHAR(150) NULL,
  deadline     VARCHAR(150) NULL,
  requirements TEXT NULL,
  fee          VARCHAR(100) NULL,
  applied_date VARCHAR(60)  NULL,
  status       VARCHAR(255) NULL,
  result       VARCHAR(30)  NULL,
  link         TEXT NULL,
  submitted_by VARCHAR(60)  NULL,
  notes        TEXT NULL,
  updated_by   INT UNSIGNED NULL,
  created_at   DATETIME NOT NULL,
  updated_at   DATETIME NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_app_import (import_key),
  KEY idx_app_student (student_id),
  CONSTRAINT fk_app_student FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE import_notes (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  student_id  INT UNSIGNED NULL,
  country     VARCHAR(20)  NULL,
  sheet       VARCHAR(120) NOT NULL,
  ref         VARCHAR(40)  NULL,
  field       VARCHAR(60)  NULL,
  note        TEXT NOT NULL,
  resolved    TINYINT(1) NOT NULL DEFAULT 0,
  created_at  DATETIME NOT NULL,
  PRIMARY KEY (id),
  KEY idx_note_student (student_id),
  CONSTRAINT fk_note_student FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE students SET country = 'italy';
UPDATE users SET countries = 'italy' WHERE role = 'officer' AND countries IS NULL;

